                        for j in range(2):
                            for k in range(2):
                                for l in range(2):
                                    product = a * b * c * d
                                    if product not in used:
                                        used.add(product)
                                        products.append(product)
                    return e in products and f in products

                if can_form(e, f):
                    results.append(sorted([e, f]))

    # Return the results sorted by the first element of each subarray
