from typing import List

def args_to_string(args: List[str] | List[List[str]]) -> str:
    """
    Converts a list of system call arguments keys and values into a single, space-delimited string.

    Each element of the list can be:
    * a single string,
    * a single string array,
    * an array of two strings.

    In the last case, the first string has a "--" prefix if it's more than one character long,
    or a "-" prefix otherwise.
    """
    result = []

    for arg in args:
        if isinstance(arg, list):
            if len(arg) == 2:
                # Handle the special case of two strings
                if len(arg[0]) > 1:
                    result.append(f"--{arg[0]} {arg[1]}")
                else:
                    result.append(f"-{arg[0]} {arg[1]}")
            else:
                # Handle the case where the list has more than two elements
                result.extend(arg)
        else:
            # Handle the case where the argument is a single string
            result.append(arg)

    return " ".join(result)

