import re

def find_codwars(url):
    # Use a regular expression to extract the domain part of the URL
    match = re.match(r'https?://(?:[^/]+/)*([^/]+)', url)
    if match:
        domain = match.group(1)
        # Check if the domain matches "codwars.com" or "subdomain.codwars.com"
        return domain == "codwars.com" or domain.startswith("subdomain.codwars.com")
    return False

import re

def find_codwars(url):
    # Regular expression to match URLs that are part of the codwars.com domain
    codwars_domain_pattern = re.compile(r'https?://(?:[a-zA-Z0-9-]+\.)?codwars\.com')

    # Check if the URL matches the codwars.com domain pattern
    return bool(codwars_domain_pattern.match(url))
